using System.Net;using System.Net.Mail;using System.Security.Cryptography;using EduForge.Domain;using EduForge.Infrastructure;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;public record RecoveryInput(string Email);public record ResetInput(string Token,string Password);
public static class RecoveryEndpoints {
 static string Hash(string value)=>Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(value)));
 public static void MapRecovery(this WebApplication app){
 app.MapPost("/api/auth/recover",async(RecoveryInput input,IConfiguration config,MaterialDbContext db,IRecoveryMailSender sender,CancellationToken ct)=>{if(input.Email is null||input.Email.Length>254||!MailAddress.TryCreate(input.Email,out _))return Results.BadRequest();if(!sender.IsConfigured)return Results.Problem("Отправка писем пока не настроена. Заполните SMTP в локальном settings.json. Для Google-аккаунта используйте вход через Google.",statusCode:503);var teacher=await db.Teachers.SingleOrDefaultAsync(x=>x.NormalizedEmail==input.Email.Trim().ToUpperInvariant(),ct);if(teacher is not null&&teacher.PasswordHash is not null){var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));var reset=new PasswordReset{TeacherId=teacher.Id,Hash=Hash(token),ExpiresAt=DateTimeOffset.UtcNow.AddMinutes(30).ToUnixTimeMilliseconds()};db.PasswordResets.Add(reset);await db.SaveChangesAsync(ct);var origin=config["Frontend:Origin"]??"http://localhost:3000";try{await sender.SendAsync(teacher.Email,origin+"/reset?token="+token,ct);}catch(Exception ex)when(ex is SmtpException or OperationCanceledException){reset.Used=true;await db.SaveChangesAsync(CancellationToken.None);if(ct.IsCancellationRequested)throw;return Results.Problem("Не удалось отправить письмо. Проверьте SMTP и пароль приложения отправителя.",statusCode:503);}}return Results.Ok(new{message="Если аккаунт с паролем существует, письмо отправлено."});}).RequireRateLimiting("auth");
 app.MapPost("/api/auth/reset",async(ResetInput input,MaterialDbContext db,IPasswordHasher<Teacher> hasher,CancellationToken ct)=>{if(input.Token is null||input.Token.Length!=64||input.Password is null||input.Password.Length<12||input.Password.Length>128)return Results.BadRequest(new{message="Нужна корректная ссылка и пароль от 12 до 128 символов."});await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var hash=Hash(input.Token);var now=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();var reset=await db.PasswordResets.SingleOrDefaultAsync(x=>x.Hash==hash&&!x.Used&&x.ExpiresAt>now,ct);if(reset is null)return Results.BadRequest(new{message="Ссылка недействительна или истекла."});var teacher=await db.Teachers.SingleAsync(x=>x.Id==reset.TeacherId,ct);teacher.PasswordHash=hasher.HashPassword(teacher,input.Password);teacher.SecurityStamp=Guid.NewGuid();reset.Used=true;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.NoContent();}).RequireRateLimiting("auth");
 }
}
